/* Inline greeting assistant: deterministic demo responses, no network or model calls. */
const homeAssistant={open:false,question:'',intent:null};
function assistantSuggestions(){return [{id:'week',text:tr('How is this week going?','这周经营怎么样？')},{id:'attention',text:tr('What needs my attention?','有什么需要我处理？')},{id:'promotion',text:tr('Help me create a promotion.','帮我起草推广文案。')}];}
function mountHomeAssistant(){arrangeHomeOverview();const greeting=document.querySelector('.intro>div:not(.header-actions)');if(!greeting)return;greeting.id='home-assistant';greeting.className='home-assistant';paintHomeAssistant(false);}
function arrangeHomeOverview(){const widgets=document.querySelector('.widgets');if(!widgets)return;const ids=pending();widgets.classList.add('compact-overview');widgets.innerHTML=`<button class="widget overview-advice" data-open="insight" aria-label="${tr('View occupancy insights','查看入住率分析')}"><span class="widget-top">${tr('Occupancy','入住率')}</span><span class="big-value">70<span>%</span></span><span class="overview-advice-title">${tr('Fill your weekdays.','抓住工作日机会。')}</span><span class="overview-advice-copy">${tr('More weekday availability. Try a midweek stay offer.','工作日空房较多，可尝试住宿推广。')}</span><span class="widget-link">${tr('View suggestion','查看建议')} ${svg('arrow')}</span></button><section class="widget overview-pending" aria-label="${tr('Needs your review','待你处理')}"><div class="widget-top"><span>${tr('Needs you','待处理')}</span><span>${ids.length}</span></div><div class="overview-tasks">${ids.length?ids.slice(0,2).map(id=>`<button data-home-task="${id}"><strong>${tx(tasks[id].title)}</strong><span>${tr(id==='reply'?'AI reply ready':id==='promotion'?'Draft ready':'Insight ready',id==='reply'?'AI 回复已准备':id==='promotion'?'草稿已准备':'分析已准备')}</span><small>${tr('Review','审核')} ${svg('arrow')}</small></button>`).join(''):`<p>${tr('All caught up.','都处理好了。')}</p>`}</div><button class="overview-all" id="overview-all">${tr('Open Work','进入工作区')} ${svg('arrow')}</button></section>`;widgets.querySelectorAll('[data-home-task]').forEach(b=>b.onclick=()=>{location.hash='work/'+b.dataset.homeTask});widgets.querySelector('#overview-all').onclick=()=>goPage('work');const heading=[...document.querySelectorAll('.section-title')].find(h=>h.textContent.includes(tr('Ready when you are','待你处理')));heading?.remove();document.querySelectorAll('.body-content>.work-card').forEach(c=>c.remove());}
function assistantIntent(question){if(/promotion|draft|create|推广|文案|起草/i.test(question))return'promotion';if(/attention|review|pending|task|确认|待办|处理|任务/i.test(question))return'attention';if(/quiet|weekday|why|工作日|平日|为什么/i.test(question))return'why';if(/nearby|market|around|周边|市场|附近/i.test(question))return'explore';if(/week|occupancy|business|going|经营|入住率|这周|本周/i.test(question))return'week';return'unknown';}
function assistantResponse(){const count=pending().length;switch(homeAssistant.intent){case'week':return{body:tr('Your occupancy is 70% this week. Weekdays are quieter than weekends: 64% compared with 85%.','本周入住率为 70%。工作日较周末安静：工作日 64%，周末 85%。'),cta:tr('See analysis','查看分析'),route:'analysis'};case'why':return{body:tr('In this sample, 18 of 50 weekday room nights remain available, compared with 3 of 20 at the weekend. These bookings show the gap, but do not establish why guests chose other dates.','示例中，工作日 50 个间夜还有 18 个可售，周末 20 个间夜还有 3 个可售。预订记录能说明差距，但不能确定客人选择其他日期的原因。'),cta:tr('Explore the evidence','查看分析依据'),route:'analysis'};case'attention':return{body:count?tr(`${count} ${count===1?'item needs':'items need'} your review. ${pending().map(id=>tx(tasks[id].title)).join(' · ')}. Nothing is sent or published automatically.`,`${count} 项工作等待你确认：${pending().map(id=>tx(tasks[id].title)).join('、')}。不会自动发送或发布。`):tr('You’re all caught up. Your confirmed work is saved in the activity history.','待确认事项都处理好了，可以在工作区查看完成记录。'),cta:tr('Open Work','打开工作区'),route:'work'};case'promotion':return{body:tr('A weekday stay draft is ready to shape. Lead with a quieter escape, then review the wording before using it. No discount or publishing is assumed.','已有一份工作日住宿推广草稿。可以突出安静小住的体验，使用前由你审核文案。不预设折扣或发布。'),cta:tr('Review promotion draft','查看推广草稿'),route:workState.confirmed.includes('promotion')?'work':'work/promotion'};case'explore':return{body:tr('Explore has a sample demand calendar, nearby stay comparisons and guest topics. These are fictional market signals, not connected OTA data.','探索页提供示例需求日历、周边住宿对比与客人话题。这些是虚构市场情境，未连接 OTA 数据。'),cta:tr('Open Explore','探索周边'),route:'explore'};default:return{body:tr('This prototype can show sample performance, work awaiting review, promotion drafts and nearby-market examples. Try a suggested question below; open-ended AI is not connected yet.','当前原型可以查看示例经营情况、待确认工作、推广草稿与周边市场。可以试试下方问题，尚未接入开放式 AI 对话。')}}}
let assistantAnimation;
function paintHomeAssistant(animate=true,focusTarget){const host=document.getElementById('home-assistant');if(!host)return;assistantAnimation?.cancel();const oldHeight=host.getBoundingClientRect().height;
if(!homeAssistant.open){host.innerHTML=`<button class="greeting-trigger" id="greeting-trigger" aria-expanded="false" aria-controls="assistant-panel"><span class="greeting-title" role="heading" aria-level="1">${tr('Hi, Alex.','你好，Alex。')}</span><span class="greeting-sub">${tr('A little clarity for your day.','让经营的每一天，更清晰。')}</span><span class="ask-ai-hint"><span aria-hidden="true">✦</span> ${tr('Ask AI','问问 AI')}</span></button>`;host.querySelector('button').onclick=()=>{homeAssistant.open=true;paintHomeAssistant(true,'assistant-question')};}
else{const response=homeAssistant.intent?assistantResponse():null;host.innerHTML=`<section id="assistant-panel" class="assistant-panel" aria-labelledby="assistant-title"><div class="assistant-heading"><h1 id="assistant-title"><span aria-hidden="true">✦</span> ${tr('What can I help with?','有什么可以帮你？')}</h1><button id="assistant-close" aria-label="${tr('Close assistant','关闭助手')}">×</button></div><p class="assistant-demo">${tr('Demo assistant · Uses sample data','演示助手 · 使用示例数据')}</p><form id="assistant-form"><label for="assistant-question" class="assistant-label">${tr('Ask about your homestay','问问你的民宿经营')}</label><div class="assistant-input-row"><input id="assistant-question" autocomplete="off" maxlength="300" placeholder="${tr('Ask about your homestay…','想了解民宿的什么？')}" required><button type="submit" aria-label="${tr('Ask question','提交问题')}">${svg('arrow')}</button></div></form>${response?`<div class="assistant-answer" role="status"><p class="assistant-asked"></p><p class="assistant-answer-copy">${response.body}</p>${response.route?`<button id="assistant-destination">${response.cta} ${svg('arrow')}</button>`:''}</div>`:''}<div class="assistant-suggestions" aria-label="${tr('Suggested questions','推荐问题')}">${assistantSuggestions().slice(0,response?2:3).map(s=>`<button type="button" data-ask="${s.id}">${s.text}</button>`).join('')}</div></section>`;
const input=host.querySelector('input');function submit(question,intent){homeAssistant.question=question.trim();homeAssistant.intent=intent||assistantIntent(question);paintHomeAssistant(true,'assistant-question')}
host.querySelector('#assistant-form').onsubmit=e=>{e.preventDefault();if(!input.value.trim()){input.setCustomValidity(tr('Please enter a question.','请输入问题。'));input.reportValidity();return;}submit(input.value)};input.oninput=()=>input.setCustomValidity('');host.querySelector('#assistant-close').onclick=()=>{homeAssistant.open=false;homeAssistant.question='';homeAssistant.intent=null;paintHomeAssistant(true,'greeting-trigger')};host.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();host.querySelector('#assistant-close')?.click()}};host.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>submit(b.textContent,b.dataset.ask));if(response){host.querySelector('.assistant-asked').textContent=homeAssistant.question;host.querySelector('#assistant-destination')?.addEventListener('click',()=>{location.hash=response.route})}}
const newHeight=host.getBoundingClientRect().height;if(animate&&motion()){assistantAnimation=host.animate([{height:oldHeight+'px',opacity:.65},{height:newHeight+'px',opacity:1}],{duration:300,easing:'cubic-bezier(.2,.7,.2,1)'});}if(focusTarget)host.querySelector('#'+focusTarget)?.focus({preventScroll:true});}
render();
